using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class ReturnedSetObservationCheck
{
 static void Need(bool v,string why){if(!v)throw new InvalidDataException(why);}
 internal static int Recorded(string input,string native,string output){var r=JsonNode.Parse(File.ReadAllText(input))!.AsObject();var e=JsonNode.Parse(File.ReadAllText(native))!.AsObject();var origin=ReturnedSurfaceSetProof.ReadOrigin(r["root"]!.GetValue<string>(),r["arguments"]!.AsObject());Need(JsonNode.DeepEquals(origin.Pins,e["originalArtifactHashes"])&&JsonNode.DeepEquals(origin.Manifest,e["authoritativeStepManifest"])&&JsonNode.DeepEquals(origin.SavedBaseline,e["savedFilesHistoricalOpenBaseline"]),"Actual Native/SDK returned-gap origin differs");File.WriteAllText(output,new JsonObject{["state"]="passed",["actualRecordedOriginMatches"]=true,["cadConnectionAttempted"]=false,["originalTimeoutModified"]=false,["copyFenceReleased"]=false,["originalOutcomeResolved"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine("PASS actual recorded Native/SDK returned-gap journal/step/verified-OPEN baseline, no CAD or authority.");return 0;}
 internal static int Run(string input,string output){var rows=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray();int cases=0;foreach(var row in rows){string root=row!["root"]!.GetValue<string>(),id=row["observationId"]!.GetValue<string>();var raw=SolidScaleProof.Raw(root,id,row["observationSha256"]!.GetValue<string>()).Value;bool good=row["fault"]!.GetValue<string>()=="control",rejected=false;try{ReturnedSurfaceSetProof.Check(root,raw,row["arguments"]!.AsObject(),true);}catch(ReferenceRejected){rejected=true;}Need(rejected!=good,"SDK returned observer refusal differs: "+row["fault"]);cases++;if(good){var origin=ReturnedSurfaceSetProof.ReadOrigin(root,row["arguments"]!.AsObject());Need(JsonNode.DeepEquals(origin.Pins,raw["originalArtifactHashes"]),"Independent original pin map differs");cases++;}}Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false,["mutationAuthorityGranted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine($"PASS: {cases} independent Framework/SDK returned-observation proofs; no CAD/authority.");return 0;}
}
